<script setup>
import { computed, reactive, ref } from 'vue'; import MButton from '../../../components/mds/MButton.vue'; import MDialog from '../../../components/mds/MDialog.vue'; import MInput from '../../../components/mds/MInput.vue'; import MMobileTopBar from '../../../components/mds/MMobileTopBar.vue'; import MSelect from '../../../components/mds/MSelect.vue'; import MTextarea from '../../../components/mds/MTextarea.vue'; import { supplierCreateDraft, toSupplierCreatePayload, validateSupplierCreateDraft } from '../domain/supplier-list.mjs';
const props=defineProps({saving:Boolean,serverError:String,safeAreaStyle:{type:Object,default:()=>({})}});const emit=defineEmits(['cancel','save']);const draft=reactive(supplierCreateDraft());const errors=reactive({});const discard=ref(false);const initial=ref(JSON.stringify(draft));const invoices=['','Hóa đơn VAT','Hóa đơn bán hàng','Không yêu cầu'].map((value)=>({value,label:value||'Chưa xác định'}));const dirty=computed(()=>JSON.stringify(draft)!==initial.value);function validate(){const next=validateSupplierCreateDraft(draft);Object.keys(errors).forEach((key)=>delete errors[key]);Object.assign(errors,next);return next;}function cancel(){if(!props.saving){if(dirty.value)discard.value=true;else emit('cancel');}}function submit(){if(!Object.keys(validate()).length)emit('save',toSupplierCreatePayload(draft));}
</script>
<template><section class="mds-mobile-app flex h-[100dvh] min-w-0 flex-col overflow-hidden bg-[var(--mds-bg)]" :style="safeAreaStyle"><MMobileTopBar title="Thêm nhà cung cấp" @back="cancel"><template #actions><MButton variant="link" :disabled="saving" @click="cancel">Hủy</MButton></template></MMobileTopBar><form class="flex min-h-0 flex-1 flex-col" novalidate @submit.prevent="submit"><main class="min-h-0 flex-1 overflow-y-auto"><p class="mds-mobile-gutter-x border-b border-[var(--mds-border-light)] py-3 text-[13px] text-[var(--mds-text-secondary)]">Không nhập phí dịch vụ, đặt cọc hoặc giao dịch tại bước này.</p><div class="mds-mobile-gutter-x space-y-4 py-4"><label><span class="mb-1.5 block text-[13px] font-medium">Tên nhà cung cấp <span class="text-[var(--mds-danger)]">*</span></span><MInput v-model="draft.name" :error="errors.name" :disabled="saving"/></label><label><span class="mb-1.5 block text-[13px] font-medium">Ngành nghề</span><MInput v-model="draft.industry" :disabled="saving"/></label><label><span class="mb-1.5 block text-[13px] font-medium">Dịch vụ cung cấp</span><MInput v-model="draft.services" :disabled="saving"/></label><label><span class="mb-1.5 block text-[13px] font-medium">Số điện thoại</span><MInput v-model="draft.contact_phone" type="tel" :disabled="saving"/></label><label><span class="mb-1.5 block text-[13px] font-medium">Email liên hệ</span><MInput v-model="draft.contact_email" type="email" :error="errors.contact_email" :disabled="saving"/></label><label><span class="mb-1.5 block text-[13px] font-medium">Mã số thuế</span><MInput v-model="draft.tax_code" :disabled="saving"/></label><label><span class="mb-1.5 block text-[13px] font-medium">Loại hóa đơn</span><MSelect v-model="draft.invoice_type" :options="invoices" :disabled="saving"/></label><label><span class="mb-1.5 block text-[13px] font-medium">Địa chỉ</span><MInput v-model="draft.address" :disabled="saving"/></label><label><span class="mb-1.5 block text-[13px] font-medium">Liên kết nhóm đặt hàng</span><MInput v-model="draft.order_group_link" type="url" :disabled="saving"/></label><label><span class="mb-1.5 block text-[13px] font-medium">Ghi chú</span><MTextarea v-model="draft.note" :rows="3" maxlength="2000" :disabled="saving"/></label><p v-if="serverError" role="alert" class="rounded-lg bg-[var(--mds-danger-bg)] px-3 py-2 text-[13px] text-[var(--mds-danger)]">{{ serverError }}</p></div></main><footer class="shrink-0 border-t border-[var(--mds-border-light)] bg-[var(--mds-bg)] px-4 pb-[calc(12px+var(--mds-mobile-safe-bottom))] pt-3"><MButton variant="primary" class="w-full" :loading="saving" :disabled="saving" @click="submit">Tạo nhà cung cấp</MButton></footer></form><MDialog v-model="discard" title="Bỏ nhà cung cấp mới?" type="danger" confirm-text="Bỏ thay đổi" @confirm="emit('cancel')"><p>Thông tin chưa lưu sẽ không được giữ lại.</p></MDialog></section></template>
